SELECT NULL, 'David Battersby', '{"name":"David Battersby","age":"62","gender":"Male","profession":"Farmer","height":"5''8\"","weight":"164lbs","physdesc":"","photoDataUrl":"","threeWords":["Shrewd","Sullen","Pessimistic"],"complication":"Betrayed","complicationNote":"","motivation":"Revenge","motivationNote":"","notes":"David Battersby is a third-generation farmer who, along with his wife Jenny, spent most of his life studying agriculture and tending crops on a farm close to the Maryland and Delaware border. During the outbreak, David and Jenny began to take in acquaintances and friends, putting them to work on the farm in return for shelter. It went well for a while. Then strangers turned up with guns and wanted the farm. David stood up to them and for a minute it looked like they were leaving. But they came back in greater numbers, killing Jenny and several others and seizing the farm as their own. David and a few companions escaped and have been on the move for the last few days. He is driven by one thought - he will not stop until he has killed the men that killed his wife.","creationMethod":"pregen","rapid":{"RSN":2,"ACU":2,"PHY":1,"INF":0,"DEX":0},"secondary":{"woundPoints":11,"resiliencePoints":7,"rangedDefense":0,"meleeDefense":1,"initiative":2,"encumbrance":7,"perception":4,"stressModifier":4,"morality":3},"skills":[{"skillName":"Animal Handling","level":0},{"skillName":"Athletics","level":1},{"skillName":"Barter","level":1},{"skillName":"Demolitions*","level":-3},{"skillName":"Driving","level":0},{"skillName":"Entertainment","level":0},{"skillName":"Farming","level":0},{"skillName":"Gambling","level":0},{"skillName":"Heavy Weapons*","level":-3},{"skillName":"Inspiration","level":0},{"skillName":"Lock-Picking*","level":2},{"skillName":"Manipulation","level":3},{"skillName":"Mechanic*","level":-3},{"skillName":"Medicine*","level":-3},{"skillName":"Melee Combat","level":2},{"skillName":"Navigation","level":1},{"skillName":"Psychology*","level":-3},{"skillName":"Ranged Combat","level":0},{"skillName":"Research","level":0},{"skillName":"Scavenging","level":1},{"skillName":"Sleight of Hand","level":2},{"skillName":"Specific Knowledge","level":0},{"skillName":"Stealth","level":2},{"skillName":"Streetwise","level":0},{"skillName":"Survival","level":1},{"skillName":"Tactics*","level":-3},{"skillName":"Tinkerer","level":0},{"skillName":"Unarmed Combat","level":2},{"skillName":"Weaponsmith*","level":-3}],"weaponPrimary":{"weaponName":"Shotgun (Sawed-Off)","condition":"Used","ammoCurrent":2},"weaponSecondary":{"weaponName":"","condition":"Used","ammoCurrent":0},"equipment":["Tent and Sleeping Bag"],"incidentalItem":"","rations":{"type":"Standard Rations","count":2},"insightDice":2,"cdp":0,"stressLevel":0,"breakingPoint":7,"lastingWounds":[],"relationships":[{"npc":"Carly McIntyre","cmod":2}]}'::jsonb, NULL, NULL, 'approved', NULL, now()
