SELECT NULL, 'Carly McIntyre', '{"name":"Carly McIntyre","age":"29","gender":"Female","profession":"Trail Guide","height":"5''5\"","weight":"139lbs","physdesc":"","photoDataUrl":"","threeWords":["Sarcastic","Confident","Strong"],"complication":"Family Obligation","complicationNote":"","motivation":"Find Safety","motivationNote":"","notes":"Born in Delaware, Carly moved to Montana with her mother after her parents divorced. She has spent the last few years as a trail guide in various parts of the US. Early in the pandemic she returned to Delaware when her father got sick and found herself unable to leave. Her father''s sister lived nearby on a farm and Carly found herself spending increasing time with her Aunt Jenny and Uncle David. When the food riots started she moved out to the farm. She was away when the strangers arrived and even if she had been there she knows she couldn''t have saved her aunt. She would like revenge but mostly she wants to feel safe again.","creationMethod":"pregen","rapid":{"RSN":0,"ACU":2,"PHY":2,"INF":0,"DEX":1},"secondary":{"woundPoints":13,"resiliencePoints":8,"rangedDefense":1,"meleeDefense":2,"initiative":3,"encumbrance":8,"perception":2,"stressModifier":2,"morality":3},"skills":[{"skillName":"Animal Handling","level":0},{"skillName":"Athletics","level":2},{"skillName":"Barter","level":1},{"skillName":"Demolitions*","level":-3},{"skillName":"Driving","level":0},{"skillName":"Entertainment","level":0},{"skillName":"Farming","level":1},{"skillName":"Gambling","level":0},{"skillName":"Heavy Weapons*","level":-3},{"skillName":"Inspiration","level":0},{"skillName":"Lock-Picking*","level":-3},{"skillName":"Manipulation","level":0},{"skillName":"Mechanic*","level":-3},{"skillName":"Medicine*","level":1},{"skillName":"Melee Combat","level":1},{"skillName":"Navigation","level":3},{"skillName":"Psychology*","level":-3},{"skillName":"Ranged Combat","level":1},{"skillName":"Research","level":0},{"skillName":"Scavenging","level":2},{"skillName":"Sle