"skillName":"Streetwise","level":0},{"skillName":"Survival","level":2},{"skillName":"Tactics*","level":-3},{"skillName":"Tinkerer","level":0},{"skillName":"Unarmed Combat","level":0},{"skillName":"Weaponsmith*","level":-3}],"weaponPrimary":{"weaponName":"Baseball Bat","condition":"Used","ammoCurrent":0},"weaponSecondary":{"weaponName":"","condition":"Used","ammoCurrent":0},"equipment":["Map of area","Tent and Sleeping Bag"],"incidentalItem":"Map of area","rations":{"type":"Standard Rations","count":2},"insightDice":2,"cdp":0,"stressLevel":0,"breakingPoint":5,"lastingWounds":[],"relationships":[]}'::jsonb, NULL, NULL, 'approved', NULL, now()
