SELECT NULL, 'Marv Calhoun', '{"name":"Marv Calhoun","age":"36","gender":"Male","profession":"Handyman","height":"5''11\"","weight":"174lbs","physdesc":"","photoDataUrl":"","threeWords":["Sarcastic","Bold","Observant"],"complication":"Addiction","complicationNote":"","motivation":"Hedonism","motivationNote":"","notes":"Raised first by his abusive uncle and aunt and later by the state, Marvin has spent much of his life drifting in and out of institutions. Paroled from Sussex Correctional Institution just months before the outbreak, Marv had found work helping David Battersby on his farm as a handyman. He has found himself feeling somewhat protective of Battersby, particularly in light of the murder of his wife Jenny. He is prepared to help get the farm back if they can find more guns and people willing to use them. Although there is no cocaine for him to get his hands on, there is no shortage of alcohol in the surrounding towns and Marv has made more than one trip without telling anyone.","creationMethod":"pregen","rapid":{"RSN":1,"ACU":2,"PHY":1,"INF":0,"DEX":1},"secondary":{"woundPoints":12,"resiliencePoints":7,"rangedDefense":1,"meleeDefense":1,"initiative":3,"encumbrance":7,"perception":3,"stressModifier":3,"morality":3},"skills":[{"skillName":"Animal Handling","level":0},{"skillName":"Athletics","level":1},{"skillName":"Barter","level":1},{"skillName":"Demolitions*","level":1},{"skillName":"Driving","level":0},{"skillName":"Entertainment","level":0},{"skillName":"Farming","level":0},{"skillName":"Gambling","level":0},{"skillName":"Heavy Weapons*","level":-3},{"skillName":"Inspiration","level":0},{"skillName":"Lock-Picking*","level":1},{"skillName":"Manipulation","level":2},{"skillName":"Mechanic*","level":2},{"skillName":"Medicine*","level":-3},{"skillName":"Melee Combat","level":2},{"skillName":"Navigation","level":0},{"skillName":"Psychology*","level":-3},{"skillName":"Ranged Combat","level":0},{"skillName":"Research","level":0},{"skillName":"Scavenging","leve